1	import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';
2	const base=path.dirname(new URL(import.meta.url).pathname.replace(/^\/(?=[A-Za-z]:)/,''));
3	const root=JSON.parse(fs.readFileSync(path.join(base,'project.json'))).project,selection=JSON.parse(fs.readFileSync(path.join(base,'active-tool.json'))),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
4	const read=ref=>fs.readFileSync(path.join(root,ref)),s=JSON.parse(read('.writer/state.json')),entry=JSON.parse(fs.readFileSync(path.join(base,'epr-entry-inventory.json'))),proof=JSON.parse(fs.readFileSync(path.join(base,'epr-exit-inventory-proof.json')));
5	assert(proof.ok);assert.equal(sha(read('.writer/state.json')),entry.state_sha256);assert.equal(s.units.length,60);assert.equal(s.revision,296);
6	const log=label=>JSON.parse(fs.readFileSync(path.join(base,'cli-logs',label,'result.json'))),out=label=>JSON.parse(fs.readFileSync(path.join(base,'cli-logs',label,'stdout.txt'))),save=(name,value)=>fs.writeFileSync(path.join(base,name),JSON.stringify(value,null,2)+'\n',{flag:'wx'});
7	const status=out('epr-entry-status'),check=out('epr-entry-check'),doctor=out('epr-entry-doctor'),issues=out('epr-issues-list'),sources=out('epr-source-list');
8	const toolParity=doctor.build.files.map(f=>{const ref=f.group==='skills'?'.agents/skills/'+f.file:f.file;const installed=sha(fs.readFileSync(path.join(selection.installed_root,ref))),external=sha(fs.readFileSync(path.join(selection.package,ref)));assert.equal(installed,f.sha256);assert.equal(external,installed);return {ref,installed_sha256:installed,external_sha256:external};});
9	const frozenVersions=Object.values(s.source_versions).map(v=>{assert.equal(sha(read(v.object_ref)),v.sha256);return {...v,ranges:s.source_ranges.filter(x=>x.version_id===v.id),consumers:s.units.filter(u=>u.source_bindings?.[v.ref]?.version_id===v.id).map(u=>u.unit)};});
10	const pages=fs.readdirSync(path.join(base,'read-pages')).filter(f=>/^epr-(ch|old).*\.json$/.test(f)).map(f=>({label:f.slice(0,-5),...JSON.parse(fs.readFileSync(path.join(base,'read-pages',f)))}));
11	const readingFiles=[...new Set(pages.map(x=>x.file))].map(file=>{const selected=pages.filter(x=>x.file===file).sort((a,b)=>a.page-b.page);const u=s.units.find(u=>path.resolve(root,u.draft)===path.resolve(file));assert(u);for(const x of selected)assert.equal(x.sha256,u.sha256);const b=fs.readFileSync(file);assert.equal(sha(b),u.sha256);return {unit:u.unit,draft:u.draft,sha256:u.sha256,pages:selected.map(x=>x.page),total_pages:selected[0].pages,total_chars:selected[0].total_chars,complete:selected.length===selected[0].pages,returned_ranges:selected.map(x=>({label:x.label,page:x.page,from:x.from,to:x.to,output_sha256:x.output_sha256}))};}).sort((a,b)=>a.unit-b.unit);
12	for(const n of [48,54,55,56,57,58,59,60])assert(readingFiles.find(x=>x.unit===n)?.complete);
13	assert.equal(pages.length,87);assert.equal(readingFiles.filter(x=>[48,54,55,56,57,58,59,60].includes(x.unit)).reduce((n,x)=>n+x.pages.length,0),74);
14	const oldQuote=(unit,quote)=>{const u=s.units[unit-1],body=read(u.draft).toString('utf8'),i=body.indexOf(quote);assert(i>=0,`${unit}: ${quote}`);return {unit,draft:u.draft,sha256:u.sha256,page:Math.floor(i/1800)+1,from:i,to:i+quote.length,quote};};
