119	  function freeze(root, input) {
120	    keys(input, ['expected_revision', 'operation_id', 'ref', 'file', 'version_id', 'previous']);
121	    return mutate(root, input, 'freeze', p => {
122	      gate(p, 'plan'); logical(p, input.ref); if (!validId(input.version_id) || Object.hasOwn(p.state.source_versions, input.version_id)) fail('SOURCE_INPUT_INVALID', 'version_id 无效或已存在');
123	      if (input.previous && version(p, input.previous).ref !== input.ref) fail('SOURCE_INPUT_INVALID', '前版必须属于同一逻辑来源');
124	      const file = safe(root, input.file ?? input.ref); text(file); const bytes = fs.readFileSync(file);
125	      const v = { id: input.version_id, ref: input.ref, object_ref: put(p, bytes), sha256: hash(bytes), previous: input.previous ?? null, format: input.ref.split('.').at(-1) };
126	      p.state.source_versions[v.id] = v; return { version: v, status: 'proposal-only-not-published' };
127	    });
128	  }
129	  function impactFor(p, input) {
130	    enabled(p); const v = version(p, input.version_id); integer(input.from, 'from');
131	    if (!['baseline', 'future', 'historical'].includes(input.mode)) fail('SOURCE_INPUT_INVALID', 'mode 仅 baseline/future/historical');
132	    if (input.mode === 'future' && input.from <= p.state.units.length) fail('SOURCE_RANGE_INVALID', 'future 只能从尚未登记的单元生效');
133	    if (input.mode === 'historical' && input.from > p.state.units.length) fail('SOURCE_RANGE_INVALID', 'historical 必须涉及已登记单元');
134	    const direct = p.state.units.filter(u => Object.hasOwn(u.source_hashes, v.ref));
135	    const earliest = direct.length ? Math.min(input.from, ...direct.map(u => u.unit)) : input.from;
136	    const reviewFrom = input.mode === 'historical' ? Math.max(1, input.from - 1) : earliest;
137	    const required = { [v.object_ref]: v.sha256 };
138	    // Dependencies are observable; semantic/indirect boundaries remain conservative.
139	    for (const u of p.state.units.filter(u => u.unit >= reviewFrom)) required[u.draft] = u.sha256;
140	    for (const u of direct) { const binding = u.source_bindings?.[v.ref]; if (binding) required[binding.object_ref] = binding.sha256; }
141	    return { schema_version: 1, revision: p.state.revision, state_sha256: hash(fs.readFileSync(safe(p.root, '.writer/state.json'))), version_id: v.id, ref: v.ref, from: input.from, mode: input.mode,
142	      candidate_sha256: v.sha256, direct_consumers: direct.map(u => ({ unit: u.unit, consumed_sha256: u.source_hashes[v.ref], bound: Boolean(u.source_bindings?.[v.ref]), affected_by_publication: u.unit >= input.from })),
143	      revision_from: input.from, review_from: reviewFrom, retained_prefix_consumers: direct.filter(u => u.unit < input.from).map(u => u.unit),
144	      replaced_ranges: p.state.source_ranges.filter(r => r.ref === v.ref && (r.to === null || r.to >= input.from)),
145	      possible_indirect_from: input.mode === 'historical' ? input.from : direct.length ? earliest : null, possible_indirect_through: direct.length ? p.state.units.length : null,
146	      possible_indirect_impact: 'unknown-requires-reading', required_readings: required,
147	      note: '仅计算可观察消费关系；模型需实读候选、旧输入与相关正文。脚本不证明语义无影响。' };
148	  }
149	  function impact(root, input) { keys(input, ['version_id', 'from', 'mode']); return { ok: true, impact: impactFor(project(root), input) }; }
150	  function reviewed(p, input) {
151	    const actual = impactFor(p, input.impact ?? {});
152	    if (!same(actual, input.impact)) fail('IMPACT_STALE', '影响预览已变化或不完整，重新 source impact 后实读');
153	    keys(input.review, ['report', 'report_sha256', 'readings', 'conclusion', 'unresolved']);
154	    string(input.review.conclusion, 'review.conclusion'); if (!Array.isArray(input.review.unresolved) || input.review.unresolved.length) fail('IMPACT_UNRESOLVED', '尚有未解决风险，不能发布；先实读并走历史修订');
155	    const report = safe(p.root, input.review.report); string(text(report), 'review.report');
156	    if (!input.review.report.startsWith('审查/') || hash(fs.readFileSync(report)) !== input.review.report_sha256 || !same(input.review.readings, actual.required_readings)) fail('IMPACT_REVIEW_INVALID', '报告、哈希或实际声明的阅读范围不完整');
157	    for (const [ref, expected] of Object.entries(actual.required_readings)) if (hash(fs.readFileSync(safe(p.root, ref))) !== expected) fail('IMPACT_STALE', '所读版本已变化');
158	    if (!input.author_evidence) fail('AUTHOR_EVIDENCE_REQUIRED', '发布/执行影响需作者授权原话');
159	    return { ...actual, review: { ...input.review, frozen_report: put(p, fs.readFileSync(report), 'txt') } };
160	  }
161	  function bindRows(p, v, from, through) {
162	    integer(from, 'from'); integer(through, 'through', from); const rows = p.state.units.filter(u => u.unit >= from && u.unit <= through && Object.hasOwn(u.source_hashes, v.ref));
163	    if (!rows.length) fail('SOURCE_BIND_EMPTY', '范围内没有实际消费者');
164	    for (const row of rows) if (row.source_hashes[v.ref] !== v.sha256) fail('SOURCE_BIND_MISMATCH', `旧单元 ${row.unit} 的消费哈希不符；找回真实旧字节或走修订，不追认当前来源`);
165	    for (const row of rows) { row.source_bindings ??= {}; row.source_bindings[v.ref] = { version_id: v.id, object_ref: v.object_ref, sha256: v.sha256 }; }
166	    return rows.map(u => u.unit);
167	  }
168	  function bind(root, input) {
169	    keys(input, ['expected_revision', 'operation_id', 'author_evidence', 'version_id', 'from', 'through']);
170	    return mutate(root, input, 'bind', p => { gate(p, 'plan'); if (!input.author_evidence) fail('AUTHOR_EVIDENCE_REQUIRED', '历史绑定需明确作者授权'); return { bound_units: bindRows(p, version(p, input.version_id), input.from, input.through), original_hashes_preserved: true }; });
171	  }
172	  function publishRange(p, v, from) {
173	    p.state.source_ranges = p.state.source_ranges.filter(r => r.ref !== v.ref || r.from < from).map(r => r.ref === v.ref && (r.to === null || r.to >= from) ? { ...r, to: from - 1 } : r);
174	    p.state.source_ranges.push({ ref: v.ref, version_id: v.id, from, to: null });
175	  }
176	  function publish(root, input) {
177	    keys(input, ['expected_revision', 'operation_id', 'author_evidence', 'impact', 'review', 'impact_id']);
178	    return mutate(root, input, 'publish', p => {
179	      if (input.impact_id) {
180	        const info = revisionInfo(p.root), pending = p.state.impact_pending[input.impact_id];
181	        if (!info || !pending) fail('REVISION_REQUIRED', '历史版本只能在对应独立修订区中发布');
182	        gate(p, 'revise', pending.from, pending.through);
183	        if (p.state.units.length >= pending.from || info.scope.from > pending.from || !input.author_evidence) fail('REVISION_REPLAY_REQUIRED', '先在修订区 rewind 最早影响单元，重新登记至原末章；发布需授权');
184	        publishRange(p, version(p, pending.version_id), pending.requested_from); delete p.state.impact_pending[input.impact_id];
185	        return { published: pending.version_id, from: pending.requested_from, pending_resolution: 'branch-only-until-transaction-commit' };
186	      }
187	      gate(p, 'plan'); const analysis = reviewed(p, input), v = version(p, analysis.version_id);
188	      if (analysis.mode === 'historical') fail('REVISION_REQUIRED', '历史变更先 source stage，再在独立修订区 replay 和提交');
189	      if (analysis.mode === 'baseline') {
190	        if (analysis.from !== 1 || p.state.source_ranges.some(r => r.ref === v.ref)) fail('SOURCE_RANGE_INVALID', 'baseline 只用于首次从第 1 单元固定原输入；其他旧消费者用 bind');
191	        if (analysis.direct_consumers.length) bindRows(p, v, 1, p.state.units.length);
192	      } else {
193	        if (analysis.direct_consumers.some(u => !u.bound)) fail('SOURCE_UNBOUND_CONSUMERS', '旧消费者尚未固定真实旧版本；先以匹配原哈希的版本 bind，不忽略旧保护');
194	        if (analysis.direct_consumers.some(u => !resolve(p, v.ref, u.unit).binding)) fail('SOURCE_BASELINE_REQUIRED', '历史消费虽已补绑，仍需 baseline 发布原输入区间，再安排未来版本，避免历史回放读取新入口');
195	        if (p.state.source_ranges.some(r => r.ref === v.ref && r.from >= analysis.from && !(r.from === analysis.from && v.previous === r.version_id))) fail('SOURCE_RANGE_INVALID', '未来发布须推进生效起点；同起点未消费版本的显式替换须 previous 指向原版本');
196	      }
197	      publishRange(p, v, analysis.from); return { published: v.id, from: analysis.from, analysis, original_hashes_preserved: true };
198	    });
199	  }
200	  function stage(root, input) {
201	    keys(input, ['expected_revision', 'operation_id', 'author_evidence', 'impact', 'review']);
202	    return mutate(root, input, 'stage-impact', p => {
203	      if (revisionInfo(p.root)) fail('REVISION_REQUIRED', '先在主作品选择执行历史变更，再建立修订会话');
204	      const analysis = reviewed(p, input); if (analysis.mode !== 'historical') fail('SOURCE_INPUT_INVALID', 'stage 只接受历史变更');
205	      const from = analysis.revision_from, through = p.state.units.length;
